59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /** Dedicated audit logger for owner lifecycle side-effects. */
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /**
70	     * Pragmatic check for a syntactically valid email address: a non-empty local
71	     * part, a single '@', and a domain with at least one dot-separated label.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
75	
76	    /**
77	     * Common street-type abbreviations expanded during address normalization,
78	     * keyed by their upper-cased form.
79	     */
80	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
81	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
82	
83	    /**
84	     * Required national-number length keyed by E.164 country calling code: a
85	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
86	     * (NANP) number carries 10. A number whose country code is listed here must have
87	     * exactly the mandated number of national digits.
88	     */
89	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
90	        Map.of("61", 9, "1", 10);
91	
92	    /**
93	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
94	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
95	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
96	     * postcode.
97	     */
98	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
99	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
100	            "QLD", new int[] {4000, 4099});
101	
102	    private final ClinicService clinicService;
103	
104	    private final OwnerMapper ownerMapper;
105	
106	    private final PetMapper petMapper;
107	
108	    private final VisitMapper visitMapper;
109	
110	    public OwnerRestControllerV1(ClinicService clinicService,
111	                                 OwnerMapper ownerMapper,
112	                                 PetMapper petMapper,
113	                                 VisitMapper visitMapper) {
114	        this.clinicService = clinicService;
115	        this.ownerMapper = ownerMapper;
116	        this.petMapper = petMapper;
117	        this.visitMapper = visitMapper;
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
123	        Collection<Owner> owners;
124	        if (lastName != null) {
125	            owners = this.clinicService.findOwnerByLastName(lastName);
126	        } else {
127	            owners = this.clinicService.findAllOwners();
128	        }
129	        if (owners.isEmpty()) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
148	        // Validate & normalize the optional email; reject the create when it is present but invalid.
149	        if (!normalizeEmail(ownerFieldsDto)) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        // Validate & normalize the optional postcode; reject the create when it is present but
153	        // not valid for the owner's city (see normalizePostcode).
154	        if (!normalizePostcode(ownerFieldsDto)) {
155	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
156	        }
157	        // Normalize the required address (trim/collapse whitespace, upper-case, expand
158	        // abbreviations) and store the normalized form back on the DTO so it is what gets
159	        // persisted and compared. Reject the create when the address is blank once normalized.
160	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
161	        if (canonicalAddress.isBlank()) {
162	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
163	        }
164	        ownerFieldsDto.setAddress(canonicalAddress);
165	        // Reject the create when the owner's city is already at capacity, i.e. it already
166	        // contains 50 or more owners (compared case-insensitively).
167	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
168	            return new ResponseEntity<>(HttpStatus.CONFLICT);
169	        }
170	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
171	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
172	        if (normalizedTelephone == null) {
173	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
174	        }
175	        ownerFieldsDto.setTelephone(normalizedTelephone);
176	        // Consolidated duplicate detection. All former separate telephone, email and household
177	        // duplicate checks are now expressed through the single derived identity key
178	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
179	        // A create is rejected only when the new owner's identity collides with an existing owner's.
180	        // Because the telephone is part of the identity, two members of the same household with
181	        // different telephones no longer collide and are both allowed; only owners that share the
182	        // same normalized telephone and email are treated as the same identity.
183	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
184	        String contactIdentity = identityContact(candidate);
185	        boolean identityInUse = this.clinicService.findAllOwners().stream()
186	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
187	        if (identityInUse) {
188	            return new ResponseEntity<>(HttpStatus.CONFLICT);
189	        }
190	        // Determine the effective registration date — the value supplied on the request, or the
191	        // server's current date when none was supplied — and roll it forward to the next business
192	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
193	        // registration date (membership-number year segment, per-day create-limit) uses this
194	        // adjusted date.
195	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
196	        if (registrationDate == null) {
197	            registrationDate = LocalDate.now();
198	        }
199	        // Reject a supplied registration date that lies in the future (later than the
200	        // server's current date): an owner cannot be registered ahead of time.
201	        else if (registrationDate.isAfter(LocalDate.now())) {
202	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
203	        }
204	        registrationDate = toBusinessDay(registrationDate);
205	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
206	        // owners have already been registered on this (adjusted) business day.
207	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
208	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        Owner owner = candidate;
212	        owner.setRegistrationDate(registrationDate);
213	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
214	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
215	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
216	        owner.setCustomerCode(customerCode(owner));
217	        // Record how many existing owners already share this owner's first and last name
218	        // (compared case-insensitively) at the moment before this owner is created.
219	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
220	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
221	        // registered on this (adjusted) business day before this owner is created.
222	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
223	        // Record the size of this owner's household after this create: the number of existing
224	        // owners sharing the same household (matching last name and address) plus this owner.
225	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
226	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
227	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
228	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
229	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
230	        // duplicate.
231	        Owner softMatch = findPossibleDuplicate(owner);
232	        owner.setPossibleDuplicate(softMatch != null);
233	        owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
234	        this.clinicService.saveOwner(owner);
235	        // Emit an audit line recording the new owner's id, customer code, registration date
236	        // and membership level.
237	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
238	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
239	            ownerMapper.membershipLevel(owner));
240	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
241	        headers.setLocation(UriComponentsBuilder.newInstance()
242	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
243	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
244	    }
245	
246	    /**
247	     * Validate and normalize the optional owner email in place.
248	     *
249	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
250	     * When present it must be a syntactically valid address; a valid address is
251	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
252	     * present but syntactically invalid, so the caller can reject with 400.
253	     */
254	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
255	        String email = ownerFieldsDto.getEmail();
256	        if (email == null || email.isBlank()) {
257	            ownerFieldsDto.setEmail(null);
258	            return true;
259	        }
260	        String normalized = email.trim().toLowerCase(Locale.ROOT);
261	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
262	            return false;
263	        }
264	        ownerFieldsDto.setEmail(normalized);
265	        return true;
266	    }
267	
268	    /**
269	     * Validate the optional owner postcode in place.
270	     *
271	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
272	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
273	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
274	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
275	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
276	     * when a postcode is present but malformed or out of range, so the caller can
277	     * reject with 400.
278	     */
279	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
280	        String postcode = ownerFieldsDto.getPostcode();
281	        if (postcode == null || postcode.isBlank()) {
282	            ownerFieldsDto.setPostcode(null);
283	            return true;
284	        }
285	        if (!postcode.matches("\\d{4}")) {
286	            return false;
287	        }
288	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
289	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
290	        if (range != null) {
291	            int value = Integer.parseInt(postcode);
292	            if (value < range[0] || value > range[1]) {
293	                return false;
294	            }
295	        }
296	        return true;
297	    }
298	
299	    /**
300	     * Normalize an owner address: trim, collapse each run of whitespace to a single
301	     * space, upper-case, and expand common street-type abbreviations
302	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
303	     * A {@code null} value normalizes to the empty string.
304	     */
305	    private static String normalizeAddress(String value) {
306	        if (value == null) {
307	            return "";
308	        }
309	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
310	        if (collapsed.isEmpty()) {
311	            return "";
312	        }
313	        String[] tokens = collapsed.split(" ");
314	        StringBuilder sb = new StringBuilder(collapsed.length());
315	        for (int i = 0; i < tokens.length; i++) {
316	            if (i > 0) {
317	                sb.append(' ');
318	            }
319	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
320	        }
321	        return sb.toString();
322	    }
323	
324	    /**
325	     * The contact portion of an owner's derived identity key: its normalized telephone and
326	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
327	     * without the household segment. Two owners share an identity when this value is equal;
328	     * because the telephone is part of it, members of one household with different telephones
329	     * do not collide. A {@code null} email contributes the empty string.
330	     */
331	    private static String identityContact(Owner owner) {
332	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
333	        String email = owner.getEmail() == null ? "" : owner.getEmail();
334	        return telephone + "|" + email;
335	    }
336	
337	    /**
338	     * Normalize an owner household field (last name or address) for duplicate detection:
339	     * trimmed, lower-cased and with all runs of whitespace collapsed to a single space.
340	     * A {@code null} value normalizes to the empty string.
341	     */
342	    private static String normalizeHouseholdKey(String value) {
343	        if (value == null) {
344	            return "";
345	        }
346	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
347	    }
348	
349	    /**
350	     * Normalize a telephone number to E.164 form.
351	     *
352	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
353	     * explicit leading {@code '+'} and country code it is kept; otherwise the
354	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
355	     * dropped from the national digits. The result must contain 8 to 15 digits
356	     * after the {@code '+'}, and — for a recognised country calling code — exactly
357	     * the national-number length that code mandates ({@code '+61'} => 9 national
358	     * digits, {@code '+1'} => 10).
359	     *
360	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
361	     *         the input is absent or cannot form a valid E.164 number.
362	     */
363	    private static String toE164(String raw) {
364	        if (raw == null) {
365	            return null;
366	        }
367	        String trimmed = raw.trim();
368	        boolean hasCountryCode = trimmed.startsWith("+");
369	        // Strip spaces, dashes and brackets.
370	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
371	        String digits;
372	        if (hasCountryCode) {
373	            // Keep the explicit country code; drop the leading '+' for validation.
374	            digits = stripped.substring(1);
375	        } else {
376	            // No country code: assume '+61' and drop a single leading '0'.
377	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
378	            digits = "61" + national;
379	        }
380	        if (!digits.matches("\\d{8,15}")) {
381	            return null;
382	        }
383	        // For a recognised country calling code, enforce the exact national-number length it
384	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
385	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
386	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
387	                .sorted((a, b) -> b.length() - a.length()).toList()) {
388	            if (digits.startsWith(countryCode)) {
389	                int nationalLength = digits.length() - countryCode.length();
390	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
391	                    return null;
392	                }
393	                break;
394	            }
395	        }
396	        return "+" + digits;
397	    }
398	
399	    /**
400	     * Count the existing owners whose first and last name match the given names,
401	     * compared case-insensitively. Used to record an owner's namesake count at the
402	     * moment before it is created.
403	     */
404	    private int countNamesakes(String firstName, String lastName) {
405	        return (int) this.clinicService.findAllOwners().stream()
406	            .filter(existing -> existing.getFirstName() != null
407	                && existing.getFirstName().equalsIgnoreCase(firstName)
408	                && existing.getLastName() != null
409	                && existing.getLastName().equalsIgnoreCase(lastName))
410	            .count();
411	    }
412	
413	    /**
414	     * Count the existing owners in the same household as the given last name and address
415	     * (compared after household-key normalization). Used, together with the owner being
416	     * created, to derive the household size recorded on the owner.
417	     */
418	    private int countHouseholdMembers(String lastName, String address) {
419	        String normalizedLastName = normalizeHouseholdKey(lastName);
420	        String normalizedAddress = normalizeHouseholdKey(address);
421	        return (int) this.clinicService.findAllOwners().stream()
422	            .filter(existing ->
423	                normalizeHouseholdKey(existing.getLastName()).equals(normalizedLastName)
424	                    && normalizeHouseholdKey(existing.getAddress()).equals(normalizedAddress))
425	            .count();
426	    }
427	
428	    /**
429	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
430	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
431	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
432	     * must be shared). When several existing owners match, the one with the lowest id is returned so
433	     * the result is deterministic. Returns {@code null} when there is no such match.
434	     */
435	    private Owner findPossibleDuplicate(Owner candidate) {
436	        if (candidate.getPostcode() == null) {
437	            return null;
438	        }
439	        return this.clinicService.findAllOwners().stream()
440	            .filter(existing -> existing.getLastName() != null
441	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
442	                && candidate.getPostcode().equals(existing.getPostcode())
443	                && !candidate.getTelephone().equals(existing.getTelephone()))
444	            .min(java.util.Comparator.comparing(Owner::getId))
445	            .orElse(null);
446	    }
447	
448	    /**
449	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
450	     *
451	     * <p>{@code REGION} is the region derived from the owner's postcode (see
452	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
453	     * SHA-256 of the normalized telephone concatenated with the last name
454	     * (e.g. {@code 'NSW-1A2B3C4D'}).
455	     */
456	    private String customerCode(Owner owner) {
457	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
458	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
459	        return region + "-" + hash8;
460	    }
461	
462	    /**
463	     * Derive the owner's region, preferring the postcode. The postcode is matched against
464	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
465	     * it is absent or in no known range does this fall back to the fixed city-to-region table
466	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
467	     */
468	    private static String deriveRegion(String postcode, String city) {
469	        if (postcode != null && postcode.matches("\\d{4}")) {
470	            int value = Integer.parseInt(postcode);
471	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
472	                int[] range = entry.getValue();
473	                if (value >= range[0] && value <= range[1]) {
474	                    return entry.getKey();
475	                }
476	            }
477	        }
478	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
479	    }
480	
481	    /**
482	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
483	     * bytes of {@code value}.
484	     */
485	    private static String sha256HexUpper(String value, int length) {
486	        try {
487	            byte[] digest = MessageDigest.getInstance("SHA-256")
488	                .digest(value.getBytes(StandardCharsets.UTF_8));
489	            StringBuilder sb = new StringBuilder(digest.length * 2);
490	            for (byte b : digest) {
491	                sb.append(String.format("%02X", b));
492	            }
493	            return sb.substring(0, length);
494	        }
495	        catch (NoSuchAlgorithmException e) {
496	            throw new IllegalStateException(e);
497	        }
498	    }
499	
500	    /**
501	     * Count the existing owners located in the given city, compared case-insensitively.
502	     * Used to derive the per-city 4-digit sequence in the customer code.
503	     */
504	    private int countOwnersInCity(String city) {
505	        return (int) this.clinicService.findAllOwners().stream()
506	            .filter(existing -> existing.getCity() != null
507	                && existing.getCity().equalsIgnoreCase(city))
508	            .count();
509	    }
510	
511	    /**
512	     * Count the existing owners whose registration date is the given (adjusted business) date.
513	     * Used to enforce the per-day sign-up limit.
514	     */
515	    private int countOwnersRegisteredOn(LocalDate date) {
516	        return (int) this.clinicService.findAllOwners().stream()
517	            .filter(existing -> date.equals(existing.getRegistrationDate()))
518	            .count();
519	    }
520	
521	    /**
522	     * Roll a registration date forward onto a business day: a Saturday or Sunday is moved to
523	     * the following Monday; a weekday is returned unchanged.
524	     */
525	    private static LocalDate toBusinessDay(LocalDate date) {
526	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
527	            || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
528	            date = date.plusDays(1);
